// Fixture — shared ontology every scenario extends. Run this on
// `main`, then tag the resulting layer as `d36-base`.
//
// `Patient` is a placeholder in the base so subsequent scenarios can
// reference it (in particular, the witness in Scenario 6's setup
// commits a `merge_comorphism for project:Patient` which needs
// Patient to already exist in the chain). Branches s1-a/b, s6-a/b,
// etc. re-declare Patient with different descriptions to create the
// IriCollision conflict the scenarios drive resolution on.

namespace core    = "urn:eigenius:core";
namespace project = "urn:project";

// --- Shared classes & properties --------------------------------

class project:Profile {
    description = "Patient profile, references Patient by IRI.";
    requires project:profile_for;
}

property project:profile_for : core:resource {
    description = "Reference to a Patient resource.";
}

property project:weight : core:float {
    description = "Patient weight in kilograms.";
}

class project:Patient {
    description = "Placeholder Patient class — scenario branches re-declare with different descriptions to drive IriCollision.";
}

// --- Animals (used in the SubclassConflict scenario, #5) --------

class project:Mammal { description = "Warm-blooded vertebrate."; }
class project:Reptile { description = "Cold-blooded vertebrate."; }

// Scenario 1 — branch A (run on `s1-a`).
// Patient as a medical-records class that requires the inherited
// `weight` property.

namespace project = "urn:project";

class project:Patient {
    description = "Medical-records Patient.";
    requires project:weight;
}

// Scenario 1 — branch B (run on `s1-b`).
// Patient with a different (billing-system) description — same IRI,
// different body, structurally an IriCollision.

namespace project = "urn:project";

class project:Patient {
    description = "Billing-system Patient.";
}

// Scenario 2 — branch A (run on `s2-a`).
// Redeclare `weight` as `core:float` (matches the fixture; the new
// layer's contribution still triggers the divergence with B).

namespace core    = "urn:eigenius:core";
namespace project = "urn:project";

property project:weight : core:float {
    description = "Weight in kg, fractional precision.";
}

// Scenario 2 — branch B (run on `s2-b`).
// Redeclare `weight` as `core:integer` — the data_type disagreement
// produces a `PropertyDataType` conflict on the merge.

namespace core    = "urn:eigenius:core";
namespace project = "urn:project";

property project:weight : core:integer {
    description = "Weight in grams as an integer.";
}

// Scenario 3 — branch A (run on `s3-a`). Same shape as Scenario 2.

namespace core    = "urn:eigenius:core";
namespace project = "urn:project";

property project:weight : core:float {
    description = "Weight in kg, fractional precision.";
}

// Scenario 3 — branch B (run on `s3-b`). Same shape as Scenario 2.

namespace core    = "urn:eigenius:core";
namespace project = "urn:project";

property project:weight : core:integer {
    description = "Weight in grams as an integer.";
}

// Scenario 4 — branch A (run on `s4-a`). Same shape as Scenario 2.

namespace core    = "urn:eigenius:core";
namespace project = "urn:project";

property project:weight : core:float {
    description = "Weight in kg, fractional precision.";
}

// Scenario 4 — branch B (run on `s4-b`). Same shape as Scenario 2.

namespace core    = "urn:eigenius:core";
namespace project = "urn:project";

property project:weight : core:integer {
    description = "Weight in grams as an integer.";
}

// Scenario 5 — branch A (run on `s5-a`).
// Dog inherits from Mammal.

namespace project = "urn:project";

class project:Dog : project:Mammal {
    description = "Domestic dog (mammal lineage).";
}

// Scenario 5 — branch B (run on `s5-b`).
// Dog inherits from Reptile — for testing only; the conflict drives
// the Restructure resolution that introduces a shared parent.

namespace project = "urn:project";

class project:Dog : project:Reptile {
    description = "Dog (reptile lineage — for testing only).";
}

// Scenario 6 — commit the take-B witness on the shared base.
//
// This is D37 §9.1 — the simplest witness: return Branch B's body
// unchanged. The compiler lowers this into:
//
// 1. A synthesised standalone Lambda at
//    `urn:eigenius:auto:lambda:<sha256>` carrying:
//      - 3 nested Lambda binders for (a, b, opt)
//      - `parameter_type` slots: Patient, Patient, Option<Patient>
//      - `program:type` = `pi a : Patient, b : Patient,
//                          opt : Option<Patient> => Patient`
//      - Body: Var "b" (returns the second parameter)
// 2. A MergeComorphism at `urn:project:patient_take_b`:
//      - `merge_target_class` = `urn:project:Patient`
//      - `merge_transformation` = <synthesised-lambda-IRI>
//
// Commit-time validators run on both and surface clean.

namespace core    = "urn:eigenius:core";
namespace project = "urn:project";

merge_comorphism project:patient_take_b for project:Patient {
    (a, b, opt) => b
}

// Scenario 6 — branch A (run on `s6-a`).
//
// Instance-level conflict: commit a Patient instance with one
// weight. Branch B will commit the same IRI with a different
// weight. The conflict's `is_a[0]` is `urn:project:Patient` (the
// Patient class the instance belongs to), which is what the
// WitnessEditor's Combobox query filters on.
//
// This differs from Scenario 1's class-level redeclaration shape
// (where both branches re-declare `class project:Patient`); Witness
// is the natural strategy for instance-level merges, while Rename
// fits class-level conflicts.

namespace project = "urn:project";

resource project:patient_42 : project:Patient {
    project:weight = 75.0;
}

// Scenario 6 — branch B (run on `s6-b`).
//
// Same IRI as branch A's instance, different weight. The merge
// classifier surfaces this as an IriCollision on
// `urn:project:patient_42` whose `is_a[0]` is `urn:project:Patient`
// — Witness picker queries against that class.

namespace project = "urn:project";

resource project:patient_42 : project:Patient {
    project:weight = 80.0;
}

// Scenario 7 — branch A (run on `s7-a`). Same shape as Scenario 1.

namespace project = "urn:project";

class project:Patient {
    description = "Medical-records Patient.";
    requires project:weight;
}

// Scenario 7 — branch B (run on `s7-b`). Same shape as Scenario 1.

namespace project = "urn:project";

class project:Patient {
    description = "Billing-system Patient.";
}

// Scenario 16 — commit the take-B witness on the sibling
// `witness-library` branch (NOT on `s6-a`).
//
// Same content as Scenario 6's witness cell. The difference is
// *where* it lives: on a separate branch off `d36-base` rather than
// on the merge target. This makes the witness off-span from any
// later s6-b → s6-a merge, so the resolver's fourth-tier walk
// (D38 §4) is required to surface it and the §3.2 off-span guard
// copies it into the merge layer.
//
// Pre-requisite: create branch `witness-library` off `d36-base` and
// switch to it before running this cell.

namespace core    = "urn:eigenius:core";
namespace project = "urn:project";

merge_comorphism project:patient_take_b for project:Patient {
    (a, b, opt) => b
}
